//! Module containing [`Led2dGenerated`], the sample struct type generated by the
//! [`led2d!`](macro@crate::led2d) macro.
//!
//! Every item on the sample pages is the macro's own output for the declaration in this
//! file, so the pages show exactly what a declaration generates.

#[cfg(not(feature = "host"))]
use crate::{
    led2d,
    led2d::{Led2dFont, LedLayout},
};

#[cfg(not(feature = "host"))]
const LED_LAYOUT_12X4: LedLayout<48, 12, 4> = LedLayout::serpentine_column_major();

#[cfg(not(feature = "host"))]
led2d! {
    pub Led2dGenerated {
        pin: PIN_3,
        led_layout: LED_LAYOUT_12X4,
        font: Led2dFont::Font3x4Trim,
    }
}
